const input = $input.first().json || {};
const prev = $('Preparar Contexto').first().json || {};

// Si ocurrió un error en la llamada del agente o en Gemini (503, 429, timeout, cuota)
if (input.error || input.status === 'error' || input.name === 'Error') {
  return [
    {
      json: {
        success: false,
        message: 'No pude responder en este momento. Intenta nuevamente.',
        errorCode: 'AGENT_UNAVAILABLE',
        retryable: true,
        quickReplies: [],
        actions: []
      }
    }
  ];
}

// 1. Busca el texto en output
// 2. Después revisa output.text
// 3. Después text
// 4. Después response
// 5. Después message
let rawOutput = '';
if (typeof input.output === 'string' && input.output.trim()) {
  rawOutput = input.output;
} else if (input.output && typeof input.output.text === 'string' && input.output.text.trim()) {
  rawOutput = input.output.text;
} else if (typeof input.text === 'string' && input.text.trim()) {
  rawOutput = input.text;
} else if (typeof input.response === 'string' && input.response.trim()) {
  rawOutput = input.response;
} else if (typeof input.message === 'string' && input.message.trim()) {
  rawOutput = input.message;
} else if (typeof input === 'string' && input.trim()) {
  rawOutput = input;
}


// 6. Convierte el resultado a string
rawOutput = (rawOutput || '').toString();

let intent = 'art_explanation';
let quickReplies = [];
let actions = [];
let requiresConfirmation = false;

// 8, 9, 10. Extraer bloque JSON opcional y validar acciones permitidas
const ALLOWED_ACTIONS = [
  'open_artist_profile',
  'open_commission',
  'open_explore',
  'open_requests',
  'open_settings'
];

let cleanMessage = rawOutput;
const jsonBlockMatch = rawOutput.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (jsonBlockMatch) {
  try {
    const parsed = JSON.parse(jsonBlockMatch[1].trim());
    if (parsed && typeof parsed === 'object') {
      if (typeof parsed.intent === 'string' && parsed.intent.trim()) {
        intent = parsed.intent.trim();
      }
      if (Array.isArray(parsed.quickReplies)) {
        quickReplies = parsed.quickReplies.filter(r => typeof r === 'string' && r.trim().length > 0);
      }
      if (Array.isArray(parsed.actions)) {
        actions = parsed.actions.filter(a => a && typeof a === 'object' && ALLOWED_ACTIONS.includes(a.type));
      }
      if (typeof parsed.requiresConfirmation === 'boolean') {
        requiresConfirmation = parsed.requiresConfirmation;
      }
      if (typeof parsed.message === 'string' && parsed.message.trim() && !cleanMessage.replace(/```(?:json)?[\s\S]*?```/g, '').trim()) {
        cleanMessage = parsed.message.trim();
      }
    }
  } catch (e) {
    // Si falla el JSON opcional, conserva el texto
  }
}

// 7. Conserva el texto visible
cleanMessage = cleanMessage.replace(/```(?:json)?[\s\S]*?```/g, '').trim();

// No permitir HTML ni JavaScript generado por Gemini
cleanMessage = cleanMessage.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
cleanMessage = cleanMessage.replace(/<\/?[a-z][a-z0-9]*\b[^>]*>/gi, '');
cleanMessage = cleanMessage.trim();

// Si el resultado queda vacío
if (!cleanMessage) {
  cleanMessage = 'No pude generar una respuesta completa. Intenta escribir tu pregunta de otra forma.';
}

if (quickReplies.length === 0) {
  quickReplies = ['Explorar artistas', 'Cómo pedir comisión', 'Teoría del color'];
}

const conversationId = (prev.conversationId || 'convo-default').toString();

return [
  {
    json: {
      success: true,
      message: cleanMessage,
      conversationId: conversationId,
      intent,
      quickReplies,
      actions,
      requiresConfirmation: Boolean(requiresConfirmation),
      provider: 'gemini',
      model: 'gemini-3.1-flash-lite',
      timestamp: new Date().toISOString()
    }
  }
];
